/* QR Lite: QR encoder local en JavaScript puro. Soporta modo byte, ECC M, versiones 1-10. */
(function(global){
'use strict';
const BLOCKS={
1:[[16,10]],2:[[28,16]],3:[[44,26]],4:[[32,18],[32,18]],5:[[43,24],[43,24]],6:[[27,16],[27,16],[27,16],[27,16]],
7:[[31,18],[31,18],[31,18],[31,18]],8:[[38,22],[38,22],[38,22],[38,22]],9:[[36,22],[36,22],[36,22],[37,22],[37,22]],10:[[43,26],[43,26],[43,26],[43,26],[44,26]]};
const ALIGN=[[],[],[6,18],[6,22],[6,26],[6,30],[6,34],[6,22,38],[6,24,42],[6,26,46],[6,28,50]];
function utf8(s){return Array.from(new TextEncoder().encode(s));}
function bits(val,len,out){for(let i=len-1;i>=0;i--)out.push((val>>>i)&1)}
function gfMul(x,y){let z=0;for(let i=7;i>=0;i--){z=(z<<1)^(((z>>>7)&1)*0x11d);z^=((y>>>i)&1)*x}return z&255}
function polyMul(p,q){let r=Array(p.length+q.length-1).fill(0);for(let i=0;i<p.length;i++)for(let j=0;j<q.length;j++)r[i+j]^=gfMul(p[i],q[j]);return r}
function generator(deg){let p=[1];let root=1;for(let i=0;i<deg;i++){p=polyMul(p,[1,root]);root=gfMul(root,2)}return p}
function ecc(data,deg){let gen=generator(deg).slice(1),res=Array(deg).fill(0);for(const b of data){let factor=b^res.shift();res.push(0);for(let i=0;i<deg;i++)res[i]^=gfMul(gen[i],factor)}return res}
function capacity(v){return BLOCKS[v].reduce((a,b)=>a+b[0],0)}
function makeCodewords(text){let data=utf8(text),v=1;while(v<10){let cc=v<10?8:16;let need=4+cc+data.length*8;if(Math.ceil(need/8)<=capacity(v))break;v++}if(v>10)throw Error('El contenido es demasiado largo para esta versión ligera. Reduce el texto.');let out=[];bits(4,4,out);bits(data.length,v<10?8:16,out);data.forEach(b=>bits(b,8,out));let max=capacity(v)*8;bits(0,Math.min(4,max-out.length),out);while(out.length%8)out.push(0);let bytes=[];for(let i=0;i<out.length;i+=8)bytes.push(out.slice(i,i+8).reduce((a,b)=>a*2+b,0));for(let pad=0;bytes.length<capacity(v);pad^=1)bytes.push(pad?0x11:0xec);
let blocks=BLOCKS[v],dataBlocks=[],ecBlocks=[];let k=0;for(const [dc,ec] of blocks){let d=bytes.slice(k,k+dc);k+=dc;dataBlocks.push(d);ecBlocks.push(ecc(d,ec))}let all=[];let maxd=Math.max(...dataBlocks.map(b=>b.length));for(let i=0;i<maxd;i++)for(const b of dataBlocks)if(i<b.length)all.push(b[i]);let maxe=Math.max(...ecBlocks.map(b=>b.length));for(let i=0;i<maxe;i++)for(const b of ecBlocks)if(i<b.length)all.push(b[i]);return {version:v,codewords:all,bytes:data.length};}
class Matrix{constructor(n){this.n=n;this.m=Array.from({length:n},()=>Array(n).fill(false));this.res=Array.from({length:n},()=>Array(n).fill(false))}set(x,y,v=true,r=true){if(x>=0&&y>=0&&x<this.n&&y<this.n){this.m[y][x]=v;if(r)this.res[y][x]=true}}get(x,y){return this.m[y][x]}}
function finder(q,x,y){for(let dy=-1;dy<=7;dy++)for(let dx=-1;dx<=7;dx++){let xx=x+dx,yy=y+dy;if(xx<0||yy<0||xx>=q.n||yy>=q.n)continue;let on=(dx>=0&&dx<=6&&dy>=0&&dy<=6&&(dx==0||dx==6||dy==0||dy==6||(dx>=2&&dx<=4&&dy>=2&&dy<=4)));q.set(xx,yy,on,true)}}
function setup(q,v){let n=q.n;finder(q,0,0);finder(q,n-7,0);finder(q,0,n-7);for(let i=8;i<n-8;i++){q.set(i,6,i%2==0,true);q.set(6,i,i%2==0,true)}for(const y of ALIGN[v])for(const x of ALIGN[v]){if((x==6&&y==6)||(x==6&&y==n-7)||(x==n-7&&y==6))continue;for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++)q.set(x+dx,y+dy,Math.max(Math.abs(dx),Math.abs(dy))!=1,true)}q.set(8,n-8,true,true);for(let i=0;i<8;i++){if(i!=6){q.res[8][i]=true;q.res[i][8]=true}}for(let i=n-8;i<n;i++){q.res[8][i]=true;q.res[i][8]=true}if(v>=7){let rem=v;for(let i=0;i<12;i++)rem=(rem<<1)^(((rem>>>11)&1)*0x1f25);let val=(v<<12)|rem;for(let i=0;i<18;i++){let bit=((val>>>i)&1)==1;let a=n-11+i%3,b=Math.floor(i/3);q.set(a,b,bit,true);q.set(b,a,bit,true)}}}
function place(q,cw){let bits=[];cw.forEach(b=>{for(let i=7;i>=0;i--)bits.push((b>>>i)&1)});let i=0,up=true,n=q.n;for(let right=n-1;right>=1;right-=2){if(right==6)right--;for(let vert=0;vert<n;vert++){let y=up?n-1-vert:vert;for(let j=0;j<2;j++){let x=right-j;if(!q.res[y][x])q.set(x,y,!!bits[i++],false)}}up=!up}}
function maskBit(mask,x,y){return [((x+y)%2)==0,(y%2)==0,(x%3)==0,((x+y)%3)==0,((Math.floor(y/2)+Math.floor(x/3))%2)==0,((x*y)%2+(x*y)%3)==0,(((x*y)%2+(x*y)%3)%2)==0,(((x+y)%2+(x*y)%3)%2)==0][mask]}
function format(q,mask){let data=(0<<3)|mask,rem=data;for(let i=0;i<10;i++)rem=(rem<<1)^(((rem>>>9)&1)*0x537);let val=((data<<10)|rem)^0x5412,n=q.n;let a=[[0,8],[1,8],[2,8],[3,8],[4,8],[5,8],[7,8],[8,8],[8,7],[8,5],[8,4],[8,3],[8,2],[8,1],[8,0]];let b=[[8,n-1],[8,n-2],[8,n-3],[8,n-4],[8,n-5],[8,n-6],[8,n-7],[8,n-8],[n-8,8],[n-7,8],[n-6,8],[n-5,8],[n-4,8],[n-3,8],[n-2,8]];for(let i=0;i<15;i++){let bit=((val>>>i)&1)==1;q.set(a[i][0],a[i][1],bit,true);q.set(b[i][0],b[i][1],bit,true)}}
function penalty(q){let n=q.n,p=0;for(let y=0;y<n;y++){let run=1,last=q.get(0,y);for(let x=1;x<n;x++){let cur=q.get(x,y);if(cur==last){run++;if(run==5)p+=3;else if(run>5)p++}else{run=1;last=cur}}}for(let x=0;x<n;x++){let run=1,last=q.get(x,0);for(let y=1;y<n;y++){let cur=q.get(x,y);if(cur==last){run++;if(run==5)p+=3;else if(run>5)p++}else{run=1;last=cur}}}for(let y=0;y<n-1;y++)for(let x=0;x<n-1;x++){let c=q.get(x,y);if(c==q.get(x+1,y)&&c==q.get(x,y+1)&&c==q.get(x+1,y+1))p+=3}let dark=0;for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(q.get(x,y))dark++;p+=Math.floor(Math.abs(dark*20-n*n*10)/(n*n))*10;return p}
function build(text){let enc=makeCodewords(text),n=17+4*enc.version,best=null,bp=1e9;for(let mask=0;mask<8;mask++){let q=new Matrix(n);setup(q,enc.version);place(q,enc.codewords);for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(!q.res[y][x]&&maskBit(mask,x,y))q.m[y][x]=!q.m[y][x];format(q,mask);let p=penalty(q);if(p<bp){bp=p;best=q}}return {size:best.n,modules:best.m,version:enc.version,bytes:enc.bytes};}
function draw(canvas,text,opt={}){let qr=build(text),size=opt.size||420,margin=Number(opt.margin??3),fg=opt.foreground||'#111827',bg=opt.background||'#fff';canvas.width=canvas.height=size;let ctx=canvas.getContext('2d'),cell=size/(qr.size+margin*2);ctx.fillStyle=bg;ctx.fillRect(0,0,size,size);ctx.fillStyle=fg;for(let y=0;y<qr.size;y++)for(let x=0;x<qr.size;x++)if(qr.modules[y][x])ctx.fillRect(Math.round((x+margin)*cell),Math.round((y+margin)*cell),Math.ceil(cell),Math.ceil(cell));return qr;}
function svg(text,opt={}){let qr=build(text),margin=Number(opt.margin??3),fg=opt.foreground||'#111827',bg=opt.background||'#fff',size=opt.size||420,unit=size/(qr.size+margin*2);let r=`<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" role="img"><rect width="100%" height="100%" fill="${bg}"/>`;for(let y=0;y<qr.size;y++)for(let x=0;x<qr.size;x++)if(qr.modules[y][x])r+=`<rect x="${((x+margin)*unit).toFixed(3)}" y="${((y+margin)*unit).toFixed(3)}" width="${unit.toFixed(3)}" height="${unit.toFixed(3)}" fill="${fg}"/>`;return r+'</svg>'}
global.QRLite={draw,svg,build};
})(window);
